const API={async makeCall(endpoint,data){try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json',},body:JSON.stringify(data)});if(!response.ok){const errorData=await response.json();throw new Error(errorData.message||`HTTP ${response.status}`);}
const result=await response.json();if(result.error){throw new Error(result.message||'API returned an error');}
return result;}catch(error){console.error(`API call to ${endpoint} failed:`,error);throw error;}},async parseRule(rule,version){return this.makeCall('/api/parse',{rule,version});},async testCommand(rule,command,version){return this.makeCall('/api/test-command',{rule,command,version});},async validateRule(rule,version){return this.makeCall('/api/validate-rule',{rule,version});},async analyzeRedundancy(rule,version){return this.makeCall('/api/analyze-redundancy',{rule,version});},async optimizeRule(rule,version){return this.makeCall('/api/optimize-rule',{rule,version});},async searchCommands(pattern,version,limit=50){return this.makeCall('/api/search-commands',{pattern,version,limit});},async getCommandInfo(command,version){return this.makeCall('/api/command-info',{command,version});},async getCategories(version){try{const response=await fetch(`/api/categories?version=${version}`);if(!response.ok){throw new Error(`HTTP ${response.status}`);}
const result=await response.json();if(result.error){throw new Error(result.message||'API returned an error');}
return result;}catch(error){console.error('API call to /api/categories failed:',error);throw error;}},async getAllCommands(version){const fullRuleResponse=await this.parseRule('+@all',version);if(fullRuleResponse&&fullRuleResponse.grouped_commands){const allCommands=new Set();Object.values(fullRuleResponse.grouped_commands).forEach(commands=>{commands.forEach(cmd=>allCommands.add(cmd));});return Array.from(allCommands).sort();}
return[];},async testCommandKey(rule,command,key,version){return this.makeCall('/api/test-command-key',{rule,command,key,version});}};export default API;